import React, { useState, useEffect } from 'react';
import { Save, X, Plus, ithub, Link, User, Code } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const ProfilePage = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [newSkill, setNewSkill] = useState('');
  
  // البيانات المطلوبة في وثيقة المشروع
  const [profileData, setProfileData] = useState({
    fullName: '',
    github: '',
    portfolio: ''
  });

  const [skills, setSkills] = useState(['React', 'Django']);

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');
      if (!token) { navigate('/'); return; }

      try {
        // تم استخدام الـ + بدلاً من الـ backticks لتجنب خطأ السطر 31
        const response = await axios.get('http://127.0.0.1:8000/api/profile/', {
          headers: { 
            'Authorization': 'Bearer ' + token 
          }
        });
        if (response.data) {
          setProfileData({
            fullName: response.data.user?.username || '',
            github: response.data.github || '',
            portfolio: response.data.portfolio || ''
          });
        }
      } catch (err) {
        console.error("Fetch Error:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchProfile();
  }, [navigate]);

  const addSkill = () => {
    if (newSkill.trim() && !skills.includes(newSkill.trim())) {
      setSkills([...skills, newSkill.trim()]);
      setNewSkill('');
    }
  };

  if (isLoading) return <div style={{ padding: '50px', textAlign: 'center' }}>Loading Digital CV...</div>;

  return (
    <div style={{ padding: '30px', backgroundColor: '#f4f7f6', minHeight: '100vh' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '35px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        
        <h2 style={{ color: '#313647', marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <User color="#4a3f6b" /> Digital CV Settings
        </h2>

        {/* حقل الاسم الكامل */}
        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', fontWeight: '600', marginBottom: '8px', color: '#435663' }}>Full Name</label>
          <input 
            style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
            value={profileData.fullName}
            onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
          />
        </div>

        {/* نظام الـ Skills Tags المطلوب */}
        <div style={{ marginBottom: '30px', padding: '20px', backgroundColor: '#fcfdfa', borderRadius: '10px', border: '1px solid #eef2e6' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600', marginBottom: '12px', color: '#435663' }}>
            <Code size={18} /> Select Technical Skills
          </label>
          
          <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
            <input 
              style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={newSkill}
              onChange={(e) => setNewSkill(e.target.value)}
              placeholder="e.g. Java, Python..."
            />
            <button 
              type="button"
              onClick={addSkill}
              style={{ padding: '10px 20px', backgroundColor: '#4a3f6b', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
            >
              <Plus size={18} />
            </button>
          </div>

          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
            {skills.map(skill => (<span key={skill} style={{ backgroundColor: '#A3B087', color: 'white', padding: '6px 15px', borderRadius: '20px', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                {skill}
                <X size={14} style={{ cursor: 'pointer' }} onClick={() => setSkills(skills.filter(s => s !== skill))} />
              </span>
            ))}
          </div>
        </div>

        {/* الروابط التقنية */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          <div>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600', marginBottom: '8px' }}>
              <Github size={18} /> GitHub Profile
            </label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={profileData.github}
              onChange={(e) => setProfileData({...profileData, github: e.target.value})}
            />
          </div>
          <div>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600', marginBottom: '8px' }}>
              <Link size={18} /> Portfolio Link
            </label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              value={profileData.portfolio}
              onChange={(e) => setProfileData({...profileData, portfolio: e.target.value})}
            />
          </div>
        </div>

        <button style={{ width: '100%', marginTop: '40px', padding: '15px', backgroundColor: '#4a3f6b', color: 'white', border: 'none', borderRadius: '10px', fontWeight: '600', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px' }}>
          <Save size={20} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
